// Canonical a,b<p: borrow correction subtracts K from the wrapped difference.
__device__ __forceinline__ void hy_sub(uint64_t out[4],const uint64_t a[4],const uint64_t b[4]) {
    uint64_t r0,r1,r2,r3;
    asm("{\n.reg .u64 t0,t1,t2,t3,k;\nsub.cc.u64 t0,%4,%8;\nsubc.cc.u64 t1,%5,%9;\nsubc.cc.u64 t2,%6,%10;\nsubc.cc.u64 t3,%7,%11;\nsubc.u64 k,0,0;\nand.b64 k,k,0x1000003D1;\nsub.cc.u64 %0,t0,k;\nsubc.cc.u64 %1,t1,0;\nsubc.cc.u64 %2,t2,0;\nsubc.u64 %3,t3,0;\n}"
        : "=l"(r0),"=l"(r1),"=l"(r2),"=l"(r3)
        : "l"(a[0]),"l"(a[1]),"l"(a[2]),"l"(a[3]),
          "l"(b[0]),"l"(b[1]),"l"(b[2]),"l"(b[3]));
    out[0]=r0;out[1]=r1;out[2]=r2;out[3]=r3;
}

__device__ __forceinline__ void hy_mul(uint64_t out[4],const uint64_t a[4],const uint64_t b[4]) {
    uint64_t tmp[5];
    qsb_field_mul(tmp,const_cast<uint64_t*>(a),const_cast<uint64_t*>(b));
    Load256(out,tmp);
    qsb_field_normalize(out);
}
